"""Plain-text absence notices for parents."""

from typing import List

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

GREETING = "Dear parent or guardian,\n\n"
CLOSING = "\n\nPlease contact the school office."

def format_day(day: date) -> str:
    return f"{day:%B} {day.day}, {day.year}"

def join_dates(days: List[date]) -> str:
    """Spell out dates: 'A', 'A and B', 'A, B and C'."""
    names = [format_day(day) for day in days]
    if len(names) <= 1:
        return "".join(names)
    return ", ".join(names[:-1]) + " and " + names[-1]

def check_marks(
    student: Student, marks: List[Mark]
) -> None:
    """Refuse marks written for another student."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(f"mark for {mark.student_id}")

def absent_days(
    student: Student, marks: List[Mark]
) -> List[date]:
    check_marks(student, marks)
    days = sorted(set(days_missed(marks)))
    if not days:
        raise ValueError("no absences to report")
    return days

def notice_text(student: Student, days: List[date]) -> str:
    noun = "day" if len(days) == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    line = f"{name} was absent on {len(days)} {noun}"
    body = f"{line}: {join_dates(days)}."
    return GREETING + body + CLOSING

def absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    """Notice for the days a student was absent."""
    return notice_text(student, absent_days(student, marks))

after.tests/test_notices.py:
import unittest
from rosterkit.notices import absence_notice, join_dates
from rosterkit.models import Mark, Student
from datetime import date

SEFA = Student("1001", "Quillon", "Sefa", "A")

def on(
    day: int, status: str, student_id: str = "1001"
) -> Mark:
    return Mark(student_id, date(2026, 9, day), status)

def notice_for(*marks: Mark) -> str:
    return absence_notice(SEFA, list(marks))

class JoinDatesTests(unittest.TestCase):
    def test_three_days(self):
        days = [date(2026, 9, d) for d in (1, 3, 5)]
        self.assertEqual(
            join_dates(days),
            "September 1, 2026, September 3, 2026 "
            "and September 5, 2026"
        )

    def test_single_day(self):
        days = [date(2026, 9, 3)]
        expected = "September 3, 2026"
        self.assertEqual(join_dates(days), expected)

class AbsenceNoticeTests(unittest.TestCase):
    def test_names_student_and_count(self):
        notice = notice_for(on(3, "absent"))
        self.assertIn("Sefa Quillon", notice)
        self.assertIn("was absent on 1 day", notice)

    def test_dates_in_order(self):
        notice = notice_for(
            on(5, "absent"), on(1, "absent")
        )
        first = notice.index("September 1, 2026")
        second = notice.index("September 5, 2026")
        self.assertLess(first, second)
        self.assertIn("was absent on 2 days", notice)

    def test_present_days_are_ignored(self):
        notice = notice_for(
            on(2, "present"), on(3, "absent")
        )
        self.assertIn("was absent on 1 day", notice)
        self.assertIn("September 3, 2026.", notice)
        self.assertNotIn("September 2", notice)

    def test_repeated_day_counts_once(self):
        notice = notice_for(
            on(3, "absent"), on(3, "absent")
        )
        self.assertIn("was absent on 1 day", notice)

    def test_late_is_not_an_absence(self):
        notice = notice_for(on(3, "late"), on(5, "absent"))
        self.assertIn("September 5, 2026.", notice)
        self.assertNotIn("September 3", notice)

    def test_excused_is_not_an_absence(self):
        notice = notice_for(
            on(3, "excused"), on(5, "absent")
        )
        self.assertIn("September 5, 2026.", notice)
        self.assertNotIn("September 3", notice)

    def test_other_student_marks_raise(self):
        other = on(4, "absent", student_id="1002")
        with self.assertRaises(ValueError):
            notice_for(on(3, "absent"), other)

    def test_no_absences_raise(self):
        marks = [on(3, "present"), on(4, "excused")]
        with self.assertRaises(ValueError):
            notice_for(*marks)

    def test_no_marks_raise(self):
        with self.assertRaises(ValueError):
            notice_for()
